#!/usr/bin/env python3
"""Collect complete native transcripts; never rewrite source files. Python 3.10+."""
from __future__ import annotations

import argparse
import contextlib
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import time
import uuid

ROOT = Path(__file__).resolve().parents[1]
SENSITIVE_KEY = re.compile(r"(?i)^(?:.*[_-])?(?:api[_-]?key|access[_-]?token|refresh[_-]?token|id[_-]?token|password|passwd|secret|authorization|cookie|email|phone|token)$")
PATTERNS = [
    re.compile(r"\bsk-(?:proj-|ant-api\d+-)?[A-Za-z0-9_-]{16,}"),
    re.compile(r"\b(?:gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})"),
    re.compile(r"\b(?:AKIA|ASIA)[A-Z0-9]{16}\b"),
    re.compile(r"\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b"),
    re.compile(r"(?i)\bBearer\s+([A-Za-z0-9._~+/-]{8,}=*)"),
    re.compile(r"(?i)\b(?:api[_-]?key|access[_-]?token|refresh[_-]?token|password|passwd|client_secret)\s*[=:]\s*['\"]?([A-Za-z0-9._~+/-]{8,}=*)"),
    re.compile(r"[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+"),
    re.compile(r"(?<!\d)01[016789][- ]?\d{3,4}[- ]?\d{4}(?!\d)"),
]


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + "." + uuid.uuid4().hex + ".tmp")
    try:
        tmp.write_bytes(data)
        os.replace(tmp, path)
    finally:
        tmp.unlink(missing_ok=True)


def write_json(path: Path, value) -> None:
    atomic_write(path, (json.dumps(value, ensure_ascii=False, indent=2) + "\n").encode())


def read_json(path: Path, default):
    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else default


def normalized(path) -> str:
    return os.path.normcase(str(Path(path).resolve()))


def within(path, parent) -> bool:
    try:
        return os.path.commonpath([normalized(path), normalized(parent)]) == normalized(parent)
    except (ValueError, OSError):
        return False


def records(data: bytes) -> list[dict]:
    # Incomplete writes are retried, never exported as a truncated prefix.
    if not data or not data.endswith(b"\n"):
        raise ValueError("empty or incomplete JSONL; retry after the source writer flushes")
    rows = []
    for line in data.splitlines():
        if not line.strip():
            continue
        row = json.loads(line)
        if not isinstance(row, dict):
            raise ValueError("JSONL row is not an object")
        rows.append(row)
    return rows


def mask(data: bytes, literals: list[str]) -> bytes:
    """Replace only value spans in original UTF-8 text, retaining JSON formatting."""
    text = data.decode("utf-8")
    found = set(literals)

    def inspect(value, depth=0):
        if depth > 12:
            return
        if isinstance(value, dict):
            for key, item in value.items():
                if SENSITIVE_KEY.fullmatch(key) and isinstance(item, str) and len(item) >= 6:
                    if not re.fullmatch(r"[A-Z_]+|\*+|\$\{?[^ ]+|<[^>]+>", item):
                        found.add(item)
                inspect(item, depth + 1)
        elif isinstance(value, list):
            for item in value:
                inspect(item, depth + 1)
        elif isinstance(value, str):
            for pattern in PATTERNS:
                for match in pattern.finditer(value):
                    found.add(match.group(1) if match.lastindex else match.group())
            if value[:1] in ("{", "["):
                try:
                    inspect(json.loads(value), depth + 1)
                except (ValueError, RecursionError):
                    pass

    for row in records(data):
        inspect(row)
    # Also covers literals occurring in nested tool argument JSON strings.
    encoded = set()
    for value in found:
        if not value or value == "****":
            continue
        for ascii_only in (False, True):
            variant = value
            for _ in range(5):
                variant = json.dumps(variant, ensure_ascii=ascii_only)[1:-1]
                encoded.add(variant)
    for value in sorted(encoded, key=len, reverse=True):
        text = text.replace(value, "****")
    # User directory names are personal data; leave separators and all other bytes intact.
    text = re.sub(r"(?i)([A-Z]:\\+(?:Users)\\+)([^\\/\"\r\n]+)", r"\1****", text)
    text = re.sub(r"(/(?:Users|home)/)([^/\\\"\r\n]+)", r"\1****", text)
    result = text.encode("utf-8")
    records(result)  # fail closed if a literal would damage JSON syntax
    if len(result.splitlines()) != len(data.splitlines()):
        raise ValueError("masking must not alter physical line count")
    return result


class Collector:
    def __init__(self, root=ROOT, codex_home=None, claude_home=None):
        self.root = Path(root).resolve()
        self.local = self.root / ".ai-logging"
        self.output = self.root / "ai-logs"
        self.codex = Path(codex_home or os.getenv("CODEX_HOME") or Path.home() / ".codex")
        self.claude = Path(claude_home or os.getenv("CLAUDE_CONFIG_DIR") or Path.home() / ".claude")

    @contextlib.contextmanager
    def lock(self):
        self.local.mkdir(parents=True, exist_ok=True)
        # OS-managed lock is released even on a crash. No unsafe stale PID deletion.
        with (self.local / "collector.lock").open("a+b") as handle:
            handle.seek(0)
            if os.name == "nt":
                import msvcrt
                if handle.read(1) == b"":
                    handle.write(b"0")
                    handle.flush()
                for attempt in range(100):
                    try:
                        handle.seek(0)
                        msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                        break
                    except OSError:
                        if attempt == 99:
                            raise RuntimeError("collector is busy; retry") from None
                        time.sleep(0.1)
                try:
                    yield
                finally:
                    handle.seek(0)
                    msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle, fcntl.LOCK_EX)
                try:
                    yield
                finally:
                    fcntl.flock(handle, fcntl.LOCK_UN)

    def sources(self):
        selected = {}
        for folder in (self.codex / "sessions", self.codex / "archived_sessions"):
            if not folder.exists():
                continue
            for path in folder.rglob("*.jsonl"):
                with path.open("rb") as handle:
                    first = handle.readline()
                try:
                    meta = json.loads(first).get("payload", {})
                except ValueError:
                    continue  # newly opened empty file is picked up next time
                if meta.get("cwd") and within(meta["cwd"], self.root):
                    relative = Path("codex") / path.relative_to(folder)
                    key = relative.as_posix()
                    if key in selected and selected[key].read_bytes() != path.read_bytes():
                        raise ValueError("conflicting active/archived Codex sources: " + key)
                    selected[key] = path
        projects = self.claude / "projects"
        if projects.exists():
            for project in projects.iterdir():
                if not project.is_dir():
                    continue
                project_matches = False
                matches = []
                for path in project.glob("*.jsonl"):
                    belongs = False
                    with path.open("rb") as handle:
                        for line in handle:
                            try:
                                cwd = json.loads(line).get("cwd")
                                if cwd and within(cwd, self.root):
                                    belongs = True
                                    break
                            except ValueError:
                                continue
                    if belongs:
                        matches.append(path)
                        project_matches = True
                # Project directory holds only this workspace's Claude sessions, including
                # empty/metadata-only sessions and nested subagent transcripts.
                if project_matches:
                    matches = list(project.rglob("*.jsonl"))
                for path in matches:
                    key = (Path("claude") / project.name / path.relative_to(project)).as_posix()
                    selected[key] = path
        return selected

    def literals(self):
        values = read_json(self.local / "redactions.local.json", [])
        if not isinstance(values, list) or any(not isinstance(x, str) or len(x) < 3 for x in values):
            raise ValueError("redactions.local.json must be a JSON array of strings, each >= 3 characters")
        return values

    def sync(self, strict=False):
        with self.lock():
            manifest = read_json(self.output / "manifest.json", {"version": 1, "files": {}})
            state = read_json(self.local / "sources.json", {})
            sources = self.sources()
            errors, changed = [], 0
            literals = self.literals()
            for relative, source in sorted(sources.items()):
                try:
                    data = source.read_bytes()
                    rows = records(data)
                    old = manifest["files"].get(relative)
                    if old and (len(data) < old["source_bytes"] or digest(data[:old["source_bytes"]]) != old["source_sha256"]):
                        raise ValueError("native source was truncated or rewritten; existing export preserved")
                    exported = mask(data, literals)
                    destination = self.output / relative
                    if old and destination.exists() and digest(destination.read_bytes()) != old["export_sha256"]:
                        raise ValueError("export was edited; existing evidence preserved")
                    entry = {
                        "tool": relative.split("/")[0],
                        "source_sha256": digest(data), "export_sha256": digest(exported),
                        "source_bytes": len(data), "export_bytes": len(exported),
                        "line_count": len(data.splitlines()),
                        "first_timestamp": next((r["timestamp"] for r in rows if "timestamp" in r), None),
                        "last_timestamp": next((r["timestamp"] for r in reversed(rows) if "timestamp" in r), None),
                        "masked": data != exported,
                    }
                    if not destination.exists() or destination.read_bytes() != exported:
                        atomic_write(destination, exported)
                        changed += 1
                    manifest["files"][relative] = entry
                    state[relative] = str(source.resolve())
                except (ValueError, OSError) as exc:
                    # Never print source content or secret values.
                    errors.append(relative + ": " + type(exc).__name__)
            if manifest["files"]:
                write_json(self.output / "manifest.json", manifest)
                write_json(self.local / "sources.json", state)
            missing = set(manifest["files"]) - set(sources)
            errors.extend(relative + ": source unavailable" for relative in sorted(missing))
            write_json(self.local / "status.json", {"checked_at": time.time(), "pid": os.getpid(), "files": len(sources), "changed": changed, "errors": errors})
            if strict and (errors or not sources):
                raise ValueError("sync incomplete: " + ("; ".join(errors) or "no project transcripts found"))
            return {"files": len(sources), "changed": changed, "errors": errors}

    def verify(self, offline=False):
        with self.lock():
            manifest = read_json(self.output / "manifest.json", {"files": {}})
            if not manifest["files"]:
                raise ValueError("no exported transcripts")
            sources = {} if offline else self.sources()
            if not offline and set(sources) != set(manifest["files"]):
                raise ValueError("source inventory differs; sync all project sessions first")
            actual = {p.relative_to(self.output).as_posix() for p in self.output.rglob("*.jsonl")}
            if actual != set(manifest["files"]):
                raise ValueError("export inventory differs from manifest")
            for relative, entry in manifest["files"].items():
                destination = self.output / relative
                if not within(destination, self.output):
                    raise ValueError("invalid manifest path")
                exported = destination.read_bytes()
                records(exported)
                if digest(exported) != entry["export_sha256"] or len(exported) != entry["export_bytes"] or len(exported.splitlines()) != entry["line_count"]:
                    raise ValueError("export integrity failure: " + relative)
                if mask(exported, self.literals()) != exported:
                    raise ValueError("unmasked values detected: " + relative)
                if not offline:
                    source = sources[relative].read_bytes()
                    if digest(source) != entry["source_sha256"] or mask(source, self.literals()) != exported:
                        raise ValueError("source changed or non-masking modification: " + relative)
            return {"verified": len(manifest["files"]), "mode": "offline-checksums" if offline else "full-source-comparison"}


def run_hook(collector):
    payload = json.load(sys.stdin)
    # A hook only triggers a complete inventory sync. It never fabricates a transcript.
    for key in ("transcript_path", "agent_transcript_path"):
        if payload.get(key) and not within(payload[key], collector.claude / "projects"):
            raise ValueError("hook transcript is outside the configured Claude projects directory")
    collector.sync()


def watch(collector, interval):
    print("Watching native Codex/Claude transcripts; interval=" + str(interval), flush=True)
    while True:
        if (collector.local / "stop").exists():
            collector.sync()
            return
        try:
            result = collector.sync()
            if result["errors"]:
                print("Collection pending/errors: " + "; ".join(result["errors"]), file=sys.stderr, flush=True)
        except (OSError, ValueError, RuntimeError) as exc:
            print("Collection error: " + type(exc).__name__, file=sys.stderr, flush=True)
        time.sleep(interval)


def background(collector):
    collector.local.mkdir(parents=True, exist_ok=True)
    # A project-wide detached worker remains active for desktop/IDE sessions too.
    status = read_json(collector.local / "watcher.json", {})
    heartbeat = read_json(collector.local / "heartbeat.json", {})
    if status.get("pid") == heartbeat.get("pid") and time.time() - heartbeat.get("time", 0) < 15:
        return {"watcher": "already-running", "pid": status["pid"]}
    (collector.local / "stop").unlink(missing_ok=True)
    options = {"cwd": str(collector.root), "stdin": subprocess.DEVNULL}
    if os.name == "nt":
        options["creationflags"] = subprocess.DETACHED_PROCESS | subprocess.CREATE_NEW_PROCESS_GROUP | subprocess.CREATE_NO_WINDOW
    else:
        options["start_new_session"] = True
    with (collector.local / "watcher.log").open("ab") as output:
        proc = subprocess.Popen([sys.executable, str(Path(__file__).resolve()), "worker"], stdout=output, stderr=output, **options)
    write_json(collector.local / "watcher.json", {"pid": proc.pid})
    return {"watcher": "started", "pid": proc.pid}


def worker(collector):
    while not (collector.local / "stop").exists():
        write_json(collector.local / "heartbeat.json", {"time": time.time(), "pid": os.getpid()})
        try:
            collector.sync()
        except (OSError, ValueError, RuntimeError) as exc:
            print("Collection error: " + type(exc).__name__, file=sys.stderr, flush=True)
        time.sleep(2)
    collector.sync()
    write_json(collector.local / "heartbeat.json", {"time": 0, "pid": os.getpid()})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=["sync", "verify", "start", "stop", "status", "watch", "worker", "hook", "run"])
    parser.add_argument("--offline", action="store_true")
    parser.add_argument("--strict", action="store_true")
    parser.add_argument("--tool", choices=["codex", "claude"])
    args, extra = parser.parse_known_args()
    collector = Collector()
    if extra and args.command != "run":
        parser.error("unexpected arguments")
    if args.command == "sync":
        result = collector.sync(args.strict)
    elif args.command == "verify":
        result = collector.verify(args.offline)
    elif args.command == "start":
        result = background(collector)
    elif args.command == "stop":
        collector.local.mkdir(parents=True, exist_ok=True)
        (collector.local / "stop").touch()
        result = {"watcher": "stop-requested"}
    elif args.command == "status":
        result = read_json(collector.local / "status.json", {"error": "not started"})
        beat = read_json(collector.local / "heartbeat.json", {})
        result["watcher_alive"] = time.time() - beat.get("time", 0) < 15
    elif args.command == "watch":
        watch(collector, 2)
        return 0
    elif args.command == "worker":
        worker(collector)
        return 0
    elif args.command == "hook":
        run_hook(collector)
        return 0
    elif args.command == "run":
        if not args.tool:
            parser.error("run requires --tool codex or --tool claude")
        cli = shutil.which(args.tool + ".cmd") if os.name == "nt" else None
        cli = cli or shutil.which(args.tool)
        if not cli:
            raise ValueError("CLI executable not found: " + args.tool)
        agent_args = extra[1:] if extra[:1] == ["--"] else extra
        if any(x == "--ephemeral" or x == "--no-session-persistence" for x in agent_args):
            raise ValueError("session persistence must remain enabled")
        background(collector)
        try:
            return subprocess.call([cli, *agent_args], cwd=collector.root)
        finally:
            collector.sync(strict=True)
    print(json.dumps(result, ensure_ascii=True))
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except (OSError, ValueError, RuntimeError) as exc:
        print("AI logging failed: " + str(exc), file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        sys.exit(130)

